from pathlib import Path
import re

path = Path('src/modules/admin/OwnerAdminV2.tsx')
s = path.read_text()

old_docs = 'supabase.from("client_documents").select("id,client_id,original_filename,validation_status,expiry_date,uploaded_at").order("uploaded_at",{ascending:false}).limit(2000),'
new_docs = 'supabase.from("client_documents").select("id,client_id,original_filename,validation_status,expiry_date,uploaded_at,is_current").eq("is_current",true).order("uploaded_at",{ascending:false}).limit(2000),'
if old_docs in s:
    s = s.replace(old_docs, new_docs)

old_req = 'setData({clients:(c.data??[]) as Row[],members:(m.data??[]) as Row[],opps:(o.data??[]) as Row[],gates:(g.data??[]) as Row[],docs:(d.data??[]) as Row[],audits:(a.data??[]) as Row[],pending:(p.data??[]) as Row[],reviews:(h.data??[]) as Row[],requests:(!rq.error&&rq.data?.ok?(rq.data.requests??[]):[]) as AccessRequest[]});'
new_req = 'if(rq.error)throw rq.error;if(!rq.data?.ok)throw new Error(rq.data?.detail||"Falha ao carregar solicitações de acesso.");\n  setData({clients:(c.data??[]) as Row[],members:(m.data??[]) as Row[],opps:(o.data??[]) as Row[],gates:(g.data??[]) as Row[],docs:(d.data??[]) as Row[],audits:(a.data??[]) as Row[],pending:(p.data??[]) as Row[],reviews:(h.data??[]) as Row[],requests:(rq.data.requests??[]) as AccessRequest[]});'
if old_req in s:
    s = s.replace(old_req, new_req)

dashboard = '''function Dashboard(p:Shared){
 const opps=useMemo(()=>{const seen=new Map<string,Row>();for(const o of p.data.opps){const k=`${String(o.client_id)}:${String(o.opportunity_id)}`;if(!seen.has(k))seen.set(k,o)}return [...seen.values()]},[p.data.opps]);
 const globalOpps=useMemo(()=>{const seen=new Map<string,Row>();for(const o of opps){const k=String(o.opportunity_id);if(!seen.has(k))seen.set(k,o)}return [...seen.values()]},[opps]);
 const due=useMemo(()=>opps.filter(o=>o.proposal_deadline&&new Date(String(o.proposal_deadline)).getTime()>=Date.now()).sort((a,b)=>new Date(String(a.proposal_deadline)).getTime()-new Date(String(b.proposal_deadline)).getTime()).slice(0,5),[opps]);
 const docPending=p.data.docs.filter(d=>["pendente_validacao","pendente","impeditivo","nao_localizado"].includes(String(d.validation_status))).length;
 const statusLabel=(v:unknown)=>String(v)==="ready"?"Ativo":String(v)==="onboarding"?"Implantação":String(v)==="inactive"?"Inativo":txt(v);
 const clientOppCount=(id:string)=>new Set(opps.filter(o=>String(o.client_id)===id).map(o=>String(o.opportunity_id))).size;
 return <main className="mx-auto max-w-[1650px] p-5"><Title title="Olá, Owner!" subtitle="Panorama operacional real do UNI." icon="⌂" onRefresh={()=>void p.load()}/><div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-6"><Metric icon="♟" label="Clientes ativos" value={p.data.clients.filter(c=>String(c.status)==="ready").length} onClick={()=>p.nav("Clientes")}/><Metric icon="＋" label="Em implantação" value={p.data.clients.filter(c=>String(c.status)==="onboarding").length} tone="violet" onClick={()=>p.nav("Clientes")}/><Metric icon="⌕" label="Oportunidades" value={globalOpps.length} tone="green" onClick={()=>p.nav("Oportunidades")}/><Metric icon="◆" label="Resultados do Gate" value={p.data.gates.length} tone="red" onClick={()=>p.nav("Negócios")}/><Metric icon="♛" label="Itens viáveis" value={p.data.gates.filter(g=>String(g.viability_status)==="viable").length} tone="amber" onClick={()=>p.nav("Negócios")}/><Metric icon="▥" label="Valor viável" value={money(p.viableValue)} tone="green" onClick={()=>p.nav("Relatórios")}/></div><div className="mt-3 grid gap-3 xl:grid-cols-[1.25fr_.75fr]"><section className={`${card} overflow-hidden`}><div className="flex items-center justify-between p-4"><h2 className="font-black">Clientes recentes</h2><button className={btn} onClick={()=>p.nav("Clientes")}>Ver todos</button></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-xs"><thead className="bg-[#f3f8fd]"><tr><th className="p-3">Cliente</th><th>Status</th><th>Oportunidades</th><th>Ação</th></tr></thead><tbody>{p.data.clients.length?p.data.clients.slice(0,6).map(c=>{const id=String(c.id);return <tr key={id} className="border-t"><td className="p-3 font-bold">{p.names.get(id)}</td><td>{statusLabel(c.status)}</td><td>{clientOppCount(id)}</td><td><button className={btn} onClick={()=>p.openModule(id,"Painel")}>Acessar</button></td></tr>}):<tr><td colSpan={4} className="p-8 text-center text-sm text-slate-500">Nenhum cliente cadastrado.</td></tr>}</tbody></table></div></section><section className={`${card} p-4`}><div className="flex items-center justify-between"><h2 className="font-black">Ações pendentes</h2><button className={btn} onClick={()=>p.nav("Habilitação")}>Abrir</button></div><div className="mt-3 space-y-2"><button onClick={()=>p.nav("Documentos")} className="flex w-full items-center justify-between rounded-lg bg-red-50 p-3 text-left"><span>Documentos pendentes/críticos</span><b>{docPending}</b></button><button onClick={()=>p.nav("Clientes")} className="flex w-full items-center justify-between rounded-lg bg-amber-50 p-3 text-left"><span>Solicitações de acesso</span><b>{p.data.requests.filter(r=>r.status==="pending").length}</b></button><button onClick={()=>p.nav("Habilitação")} className="flex w-full items-center justify-between rounded-lg bg-blue-50 p-3 text-left"><span>Pendências operacionais</span><b>{p.openPend.length}</b></button></div></section></div><section className={`${card} mt-3 p-4`}><div className="flex items-center justify-between"><h2 className="font-black">Próximos eventos</h2><button className={btn} onClick={()=>p.nav("Oportunidades")}>Abrir oportunidades</button></div><div className="mt-3 grid gap-2 md:grid-cols-2 xl:grid-cols-5">{due.length?due.map(o=><button key={`${String(o.client_id)}-${String(o.opportunity_id)}`} onClick={()=>p.openModule(String(o.client_id),"Oportunidades",String(o.opportunity_id))} className="rounded-lg border p-3 text-left hover:border-blue-300"><b className="text-xs">{txt(o.process_number,"Processo")}</b><p className="mt-1 text-[10px] text-slate-500">{txt(o.buyer_name)}</p><p className="mt-2 text-[10px] font-bold text-blue-700">{date(o.proposal_deadline)}</p></button>):<p className="text-sm text-slate-500">Nenhum prazo futuro encontrado.</p>}</div></section></main>}

function Clients'''

s2, n = re.subn(r'function Dashboard\(p:Shared\)\{.*?\n\nfunction Clients', dashboard, s, count=1, flags=re.S)
if n != 1:
    raise SystemExit('Dashboard function not found exactly once')
path.write_text(s2)
